`timescale 1ns/1ps
// Generated by hls from examples/overflow/overflow.txt, asap schedule.
// Each op, its steps and its unit:
//   X_1 = A_0 - B_0    step 1, sub0
//   Y_1 = 65535 + A_0  step 1, add0
//   Z_1 = 300 * 300    step 1, mul0
//   W_1 = X_1 * Y_1    step 2, mul0
module hls_core (
    input             clk,
    input             rst,
    input             step,
    /* verilator lint_off UNUSED */
    input      [11:0] sw,      // input slots: A_0 = SW11-8, B_0 = SW7-4, SW3-0 unused
    /* verilator lint_on UNUSED */
    input      [5:0]  code,    // observe code
    output reg [15:0] value,
    output reg        valid,   // 0 = show ----
    output reg [7:0]  state,   // 0 = IDLE, 1-2 = steps, 3 = DONE
    output            done
);
    localparam DONE = 8'd3;

    reg [15:0] A_0, B_0, X_1, Y_1, Z_1, W_1;

    // FSM outputs.
    reg mul0_sel_a, mul0_sel_b;
    reg add0_busy, sub0_busy, mul0_busy;
    reg X_1_we, Y_1_we, Z_1_we, W_1_we;

    // Units and their input muxes.
    reg  [15:0] mul0_a, mul0_b;
    wire [15:0] add0_y, sub0_y, mul0_y;

    adder      add0 (.a(16'd65535), .b(A_0),    .y(add0_y));
    subtractor sub0 (.a(A_0),       .b(B_0),    .y(sub0_y));
    multiplier mul0 (.a(mul0_a),    .b(mul0_b), .y(mul0_y));

    always @* begin
        case (mul0_sel_a)
            1'd0:    mul0_a = 16'd300;
            default: mul0_a = X_1;
        endcase
        case (mul0_sel_b)
            1'd0:    mul0_b = 16'd300;
            default: mul0_b = Y_1;
        endcase
    end

    // Sequencer: one state per step pulse, stopping at DONE.
    always @(posedge clk)
        if (rst) state <= 8'd0;
        else if (step && state != DONE) state <= state + 8'd1;

    assign done = (state == DONE);

    // Moore outputs: each step's mux selects, busy units and register writes.
    always @* begin
        mul0_sel_a = 1'd0; mul0_sel_b = 1'd0; add0_busy = 1'b0; sub0_busy = 1'b0; mul0_busy = 1'b0;
        X_1_we = 1'b0; Y_1_we = 1'b0; Z_1_we = 1'b0; W_1_we = 1'b0;
        case (state)
            8'd1: begin
                add0_busy = 1'b1; sub0_busy = 1'b1; mul0_sel_a = 1'd0; mul0_sel_b = 1'd0;
                mul0_busy = 1'b1; X_1_we = 1'b1; Y_1_we = 1'b1; Z_1_we = 1'b1;
            end
            8'd2: begin
                mul0_sel_a = 1'd1; mul0_sel_b = 1'd1; mul0_busy = 1'b1; W_1_we = 1'b1;
            end
            default: ;
        endcase
    end

    // Inputs follow the switches in IDLE; results are written on the step pulse that ends their step.
    always @(posedge clk)
        if (rst) begin
            A_0 <= 16'd0; B_0 <= 16'd0; X_1 <= 16'd0; Y_1 <= 16'd0; Z_1 <= 16'd0; W_1 <= 16'd0;
        end else begin
            if (state == 8'd0) begin
                A_0 <= {12'd0, sw[11:8]};
                B_0 <= {12'd0, sw[7:4]};
            end
            if (step && X_1_we) X_1 <= sub0_y;
            if (step && Y_1_we) Y_1 <= add0_y;
            if (step && Z_1_we) Z_1 <= mul0_y;
            if (step && W_1_we) W_1 <= mul0_y;
        end

    // Observe codes: units, then results in equation order, then inputs.
    always @* begin
        value = 16'd0; valid = 1'b0;
        case (code)
            6'd0: begin value = add0_y; valid = add0_busy; end
            6'd1: begin value = sub0_y; valid = sub0_busy; end
            6'd2: begin value = mul0_y; valid = mul0_busy; end
            6'd3: begin value = X_1; valid = state > 8'd1; end
            6'd4: begin value = Y_1; valid = state > 8'd1; end
            6'd5: begin value = Z_1; valid = state > 8'd1; end
            6'd6: begin value = W_1; valid = state > 8'd2; end
            6'd7: begin value = A_0; valid = 1'b1; end
            6'd8: begin value = B_0; valid = 1'b1; end
            default: ;
        endcase
    end
endmodule
